export function uniqueSlug(input: string, taken: Iterable<string>): string {
  const base = slugify(input) || "item";
  const used = new Set(taken);
  if (!used.has(base) && !isReservedSlug(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique suffixes");
}

/**
 * Base slug for a workspace created from a person's display name.
 *
 * `uniqueSlug` already skips reserved words and suffixes collisions. A result
 * shorter than the minimum is not usable, and when nothing usable is left the
 * base is `workspace` (still suffixed by `deriveWorkspaceSlug` when taken).
 */
export function workspaceSlugBase(displayName: string): string {
  const base = slugify(displayName);
  return base.length >= SLUG_MIN_LENGTH ? base : "workspace";
}

/** First-workspace slug. Never reserved, never shorter than the minimum. */
export function deriveWorkspaceSlug(
  displayName: string,
  taken: Iterable<string>,
): string {
  return uniqueSlug(workspaceSlugBase(displayName), taken);
}

