/** How long a password-reset link stays usable. */
const RESET_TTL_MS = 60 * 60 * 1000;

function assertWithinRateLimit(verdict: RateLimitVerdict, bucket: string): void {
  if (!verdict.allowed) {
    throw new RateLimitedError(bucket, verdict.resetAt);
  }
}

/**
 * `<display name>'s workspace`, shortened from the left of the suffix until
 * the workspace schema accepts the name.
 */
function workspaceName(displayName: string): string {
  const nameSchema = createOrganizationSchema.shape.name;
  let base = displayName;
  let candidate = `${base}${WORKSPACE_SUFFIX}`;
  while (base.length > 0 && !nameSchema.safeParse(candidate).success) {
    base = base.slice(0, -1);
    candidate = `${base}${WORKSPACE_SUFFIX}`;
  }
  return candidate;
}

function isUniqueConstraint(error: unknown): boolean {
  const seen = new Set<unknown>();
  let current: unknown = error;
  while (current && typeof current === "object" && !seen.has(current)) {
    seen.add(current);
    const code = "code" in current ? String((current as { code: unknown }).code) : "";
    const message = current instanceof Error ? current.message : "";
    if (
      code.includes("SQLITE_CONSTRAINT") ||
      message.includes("UNIQUE constraint failed")
    ) {
      return true;
    }
    current = "cause" in current ? (current as { cause: unknown }).cause : undefined;
  }
  return false;
}

/**
 * Registration creates the user and their first workspace in one step — a
 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  assertWithinRateLimit(verdict, REGISTER_BUCKET);

  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new DuplicateAccountError();
  }

  let user: User;
  try {
    user = await userRepo.insertUser({
      email: input.email,
      name: input.name,
      passwordHash: await hashPassword(input.password),
    });
  } catch (error) {
    if (isUniqueConstraint(error)) throw new DuplicateAccountError();
    throw error;
  }

  const slugBase = workspaceSlugBase(input.name);
  const taken = await orgRepo.listTakenOrgSlugs(slugBase);
  const slug = deriveWorkspaceSlug(input.name, taken);

  const org = await createOrganization(user.id, {
    name: workspaceName(input.name),
    slug,
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

