describe("sign-up", () => {
  it("signs up reserved, short, and non-latin names", async () => {
    const cases = ["Admin", "Billing", "Support", "Taskflow", "Al", "J", "山田"];
    for (const name of cases) {
      const { user, org } = await register(
        input(name, `${name}@names.example`),
      );
      expect(user.email).toBe(`${name.toLowerCase()}@names.example`);
      expect(org.name.endsWith("'s workspace")).toBe(true);
      expect(org.name.length).toBeLessThanOrEqual(64);
      expect(org.name.length).toBeGreaterThanOrEqual(2);
      expect(isValidSlug(org.slug)).toBe(true);
      expect(isReservedSlug(org.slug)).toBe(false);
      expect(org.plan).toBe("free");
      expect(org.trialEndsAt).toBeNull();
      const subscription = await subscriptionRepo.findSubscription(org.id);
      expect(subscription?.plan).toBe("free");
      expect(subscription?.status).toBe("active");
    }

    const jay = await register(input("J", "jay2@names.example"));
    const yamada = await register(input("山田", "yamada2@names.example"));
    expect([jay.org.slug, yamada.org.slug].sort()).toEqual(
      ["workspace", "workspace-2"].sort(),
    );
  });

  it("shortens a long display name and still ends with the suffix", async () => {
    const name = "N".repeat(80);
    const { org } = await register(input(name, "long@names.example"));
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
    expect(org.name.startsWith("N")).toBe(true);
  });

  it("treats email case as one account and refuses the duplicate", async () => {
    const joined: unknown[] = [];
    const off = subscribe("member.joined", (payload) => {
      joined.push(payload);
    });
    const first = await register(input("Alice", "Alice@Example.com"));
    expect(first.user.email).toBe("alice@example.com");
    expect(joined).toHaveLength(1);
    off();

    const signedIn = await login({
      email: "alice@example.com",
      password: PASSWORD,
      rememberMe: false,
    });
    expect(signedIn.user.id).toBe(first.user.id);

    await expect(register(input("Alice", "ALICE@example.com"))).rejects.toMatchObject({
      name: "DuplicateAccountError",
    });
    try {
      await register(input("Alice", "alice@example.com"));
    } catch (error) {
      expect(toAppError(error).code).toBe("conflict");
    }
    const rows = getDb().select().from(users).all();
    expect(rows.filter((row) => row.email === "alice@example.com")).toHaveLength(1);
  });

  it("throttles sign-up before writing and maps the refusal", async () => {
    const capacity = getBucketConfig("auth:register").capacity;
    for (let i = 0; i < capacity; i += 1) {
      expect((await consumeRateLimit(ANON, "auth:register")).allowed).toBe(true);
    }
    const before = getDb().select().from(users).all().length;
    await expect(register(input("Ada", "ada@limit.example"))).rejects.toBeInstanceOf(
      RateLimitedError,
    );
    try {
      await register(input("Ada", "ada@limit.example"));
    } catch (error) {
      const shape = toAppError(error);
      expect(shape.code).toBe("rate_limited");
      expect(shape.code).not.toBe("internal_error");
    }
    expect(getDb().select().from(users).all().length).toBe(before);
  });

  it("maps a throttled sign-in and reset confirmation, and stays silent on reset request", async () => {
    const loginCapacity = getBucketConfig("auth:login").capacity;
    for (let i = 0; i < loginCapacity; i += 1) {
      await consumeRateLimit(ANON, "auth:login");
    }
    try {
      await login({ email: "nobody@example.com", password: "x", rememberMe: false });
      expect.fail("login should throttle");
    } catch (error) {
      expect(toAppError(error).code).toBe("rate_limited");
    }

    resetRateLimits();
    const resetCapacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < resetCapacity; i += 1) {
      await consumeRateLimit(ANON, "auth:password-reset");
    }
    await expect(
      requestPasswordReset({ email: "nobody@example.com" }),
    ).resolves.toBeUndefined();
    try {
      await confirmPasswordReset({
        token: "t".repeat(16),
        password: PASSWORD,
        confirmPassword: PASSWORD,
      });
      expect.fail("confirm should throttle");
    } catch (error) {
      expect(toAppError(error).code).toBe("rate_limited");
    }
  });
});

